import { galleryStudyFeatures, galleryStudyCollections } from '../data/galleryDesignStudies.js';
import { preloadExhibitionImage } from './exhibitionImage.js';

export function galleryStudyImage(name) {
  return `/assets/img/projects/gallery-experience/${name}.webp?v=${['arrival', 'wall-writing', 'globe', 'rooms', 'afterword'].includes(name) ? '20260927-3' : '20260925'}`;
}

export function galleryStudyFilm(name, extension = 'mp4') {
  return `/assets/video/gallery-experience/${name}.${extension}${name === 'translation' ? '' : '?v=20260920'}`;
}

const mediaRequests = new Map();

function preloadMedia(source) {
  if (mediaRequests.has(source)) return mediaRequests.get(source);
  // Read the whole response so later media range requests can use the cached file.
  const request = fetch(source, { cache: 'force-cache', priority: 'low' })
    .then(response => {
      if (!response.ok) throw new Error('Design media unavailable');
      return response.blob();
    })
    .then(() => undefined)
    .catch(error => { mediaRequests.delete(source); throw error; });
  mediaRequests.set(source, request);
  return request;
}

export function preloadExhibitionStudies() {
  const ids = galleryStudyCollections.filter(group => ['exhibition', 'atmosphere'].includes(group.id)).flatMap(group => group.ids);
  const features = galleryStudyFeatures.filter(feature => ids.includes(feature.id));
  return Promise.allSettled(features.flatMap(feature => [
    preloadExhibitionImage(galleryStudyImage(feature.image), { maxDimension: 0, priority: 'low' }),
    ...(feature.video ? [preloadMedia(galleryStudyFilm(feature.video))] : []),
    ...(feature.sound ? [preloadMedia(galleryStudyFilm('audio', 'vtt'))] : []),
  ]));
}
